SELECT (DATE_TRUNC('DAY', "EVENT_AT")) AS "TIME_BUCKET", SUM(CASE WHEN IS_SUCCESS = 'NO' THEN 1 ELSE 0 END) AS "SEC_FAILED_LOGINS" FROM (SELECT "EVENT_ID" AS EVENT_ID, (TRY_TO_TIMESTAMP_NTZ("EVENT_TIMESTAMP")) AS EVENT_AT, "EVENT_TYPE" AS EVENT_TYPE, "USER_NAME" AS USER_NAME, "CLIENT_IP" AS CLIENT_IP, "REPORTED_CLIENT_TYPE" AS CLIENT_TYPE, "REPORTED_CLIENT_VERSION" AS CLIENT_VERSION, "FIRST_AUTHENTICATION_FACTOR" AS FIRST_AUTH_FACTOR, "SECOND_AUTHENTICATION_FACTOR" AS SECOND_AUTH_FACTOR, "IS_SUCCESS" AS IS_SUCCESS, "ERROR_CODE" AS ERROR_CODE, "ERROR_MESSAGE" AS ERROR_MESSAGE, (NULL) AS ACCOUNT_NAME /* The account these rows came from (see the ACCOUNT_OF shim). */ FROM login_history) AS base GROUP BY (DATE_TRUNC('DAY', "EVENT_AT")) ORDER BY "SEC_FAILED_LOGINS" DESC NULLS LAST, "TIME_BUCKET" LIMIT 100
